#!/usr/bin/env node
/* tools/bundle.js: makes a faster copy of the app in dist/ without touching the source.   node tools/bundle.js [root]
   The loader asks for about 130 separate cookbook files. Each is a request, and a phone on a weak connection pays for every one.
   This joins them into ONE file (cookbook/cookbook-all.js) in the same order, rewrites the file lists in dist/index.html and dist/sw.js,
   and leaves everything else as it is. Upload dist/ instead of the project folder. Source files stay separate for editing.
   Safety nets: every file is syntax-checked first, and after joining it loads the recipes both ways (separate files and the bundle) and
   refuses to finish unless both give exactly the same recipes. */
"use strict";
const fs=require("fs"),path=require("path"),vm=require("vm");
const root=path.resolve(process.argv[2]||process.cwd()),dist=path.join(root,"dist");
const rd=f=>fs.readFileSync(path.join(root,f),"utf8");
const die=m=>{console.error("ERROR: "+m);process.exit(1)};
const list=(src,re)=>{const m=re.exec(src);return m?[...m[1].matchAll(/"([^"]+)"/g)].map(x=>x[1]):null};

const FILES=list(rd("index.html"),/var FILES=\[([^\]]*)\]/);if(!FILES)die("could not find the FILES list in index.html");
const books=FILES.filter(f=>/^cookbook\//.test(f));if(books.length<2)die("fewer than 2 cookbook files in FILES: nothing to join");
const missing=books.filter(f=>!fs.existsSync(path.join(root,f)));if(missing.length)die(missing.length+" cookbook file(s) in FILES do not exist, for example "+missing[0]+" (run tools/check-links.js)");

/* 1. syntax-check, then join */
let out="/* cookbook/cookbook-all.js: GENERATED by tools/bundle.js from "+books.length+" cookbook files. Do not edit; edit the source files and run the bundler again. */\n";
for(const f of books){const src=rd(f);try{new vm.Script(src,{filename:f})}catch(e){die(f+": syntax error: "+e.message)}out+="\n/* ---- "+f+" ---- */\n"+src.replace(/\s+$/,"")+"\n;\n"}

/* 2. prove it gives the same recipes as the separate files */
const load=files=>{
 const w={};w.window=w;w.localStorage={getItem(){return null},setItem(){}};
 const noop=()=>{},el=()=>({addEventListener:noop,appendChild:noop,append:noop,classList:{add:noop,remove:noop,toggle:noop},style:{},setAttribute:noop,querySelector:()=>null,querySelectorAll:()=>[]});
 const ctx=vm.createContext(Object.assign(w,{document:{addEventListener:noop,createElement:el,head:el(),body:el(),getElementById:()=>null,querySelector:()=>null,querySelectorAll:()=>[]},console:{log:noop,warn:noop,error:noop},setTimeout,clearTimeout,Intl}));
 for(const f of files)vm.runInContext(typeof f==="string"?rd(f):f.src,ctx,{filename:typeof f==="string"?f:f.name});
 return w.KITCHEN};
let same="skipped";
try{
 const head=["kitchen.js","ingredients.js"].filter(f=>FILES.includes(f));
 const a=load(head.concat(books)),b=load(head.concat([{name:"cookbook-all.js",src:out}]));
 const sig=K=>K.recipes.map(r=>r.id+"|"+r.title+"|"+r.min+"|"+r.ids.join(",")+"|"+r.steps.join("¶")).join("\n");
 if(!a||!b||!a.recipes.length)throw new Error("the recipe catalog did not load in the test sandbox");
 if(a.recipes.length!==b.recipes.length||sig(a)!==sig(b))die("the bundle gives different recipes ("+b.recipes.length+") than the separate files ("+a.recipes.length+"). Nothing was written.");
 same=a.recipes.length+" recipes identical both ways"
}catch(e){if(/different recipes/.test(e.message))throw e;console.warn("warning: could not run the same-recipes test ("+e.message+"). The bundle is a plain join of syntax-checked files, but test the app before uploading.")}

/* 3. write dist/: a copy of the project (minus dist, tools, .git, node_modules, notes) with the bundle swapped in */
const skip=n=>["dist","tools",".git","node_modules"].includes(n)||/\.md$/i.test(n);
fs.rmSync(dist,{recursive:true,force:true});
const copy=(from,to)=>{fs.mkdirSync(to,{recursive:true});for(const n of fs.readdirSync(from)){if(from===root&&skip(n))continue;const s=path.join(from,n),d=path.join(to,n);fs.statSync(s).isDirectory()?copy(s,d):fs.copyFileSync(s,d)}};
copy(root,dist);
for(const f of books)fs.rmSync(path.join(dist,f),{force:true});
fs.mkdirSync(path.join(dist,"cookbook"),{recursive:true});fs.writeFileSync(path.join(dist,"cookbook/cookbook-all.js"),out);
const swap=(file,re)=>{const p=path.join(dist,file);let s=fs.readFileSync(p,"utf8");
 const m=re.exec(s);if(!m)die("could not find the file list in "+file);
 let placed=false;const items=[...m[1].matchAll(/"([^"]+)"/g)].map(x=>x[1]).flatMap(f=>{if(/^cookbook\//.test(f)){if(placed)return[];placed=true;return["cookbook/cookbook-all.js"]}return[f]});
 fs.writeFileSync(p,s.replace(m[0],m[0].replace(m[1],items.map(x=>'"'+x+'"').join(","))))};
swap("index.html",/var FILES=\[([^\]]*)\]/);swap("sw.js",/F=\[([^\]]*)\]/);

const kb=n=>(n/1024).toFixed(0)+" KB";
console.log("dist/ written: "+books.length+" cookbook files joined into cookbook/cookbook-all.js ("+kb(out.length)+"), "+same+".");
console.log("Requests at start: "+FILES.length+" -> "+(FILES.length-books.length+1)+". Upload the dist/ folder.");
